from _lib import *
lesson("participle-clauses", "Zdania imiesłowowe", "Zdania z imiesłowem (participle clauses)", 6,
 "Zdanie imiesłowowe to skrócona wersja zdania podrzędnego. Zamiast 'Because I felt tired, I went to bed' mówimy 'Feeling tired, I went to bed'. Używamy: imiesłowu czynnego -ing (czynność równoczesna lub przyczyna), imiesłowu biernego -ed/3. forma (znaczenie bierne) oraz having + past participle (czynność wcześniejsza).",
 "Zdania imiesłowowe są typowe dla pisma formalnego i literackiego. Pozwalają łączyć informacje zwięźle – egzaminatorzy C1 wysoko cenią je w kryterium 'Language'.",
 dict(scheme="-ing …, zdanie główne | Having + past participle …, zdanie główne | Past participle …, zdanie główne", word_order="Walking home, I met Tom. / Having finished the report, she left. / Built in 1890, the bridge is still used.",
      affirmative=["Knowing the risks, he still went ahead.", "Having lived abroad, she understands culture shock.", "Written in simple language, the book is easy to read."],
      negative=["Not knowing what to do, I called my mum.", "Not having received a reply, we wrote again."],
      questions=["Zdania imiesłowowe nie tworzą pytań – są częścią zdania oznajmującego."]),
 [X("Opening the door, she saw a stranger.", "Otwierając drzwi, zobaczyła nieznajomego.", "Czynność równoczesna."),
  X("Feeling ill, he stayed at home.", "Ponieważ źle się czuł, został w domu.", "Przyczyna."),
  X("Having finished his homework, he went out.", "Odrobiwszy lekcje, wyszedł.", "Czynność wcześniejsza → having + past participle."),
  X("Not wanting to disturb her, I left a note.", "Nie chcąc jej przeszkadzać, zostawiłem kartkę.", "Przeczenie: not przed imiesłowem."),
  X("Founded in 1364, the university is one of the oldest in Europe.", "Założony w 1364 roku uniwersytet jest jednym z najstarszych w Europie.", "Znaczenie bierne → past participle."),
  X("Shocked by the news, she couldn't speak.", "Zszokowana wiadomością, nie mogła mówić.", "Bierne – coś ją zszokowało."),
  X("Having been warned, they took extra care.", "Ponieważ zostali ostrzeżeni, zachowali szczególną ostrożność.", "Having been + past participle: bierne i wcześniejsze."),
  X("The man sitting next to me was snoring.", "Mężczyzna siedzący obok mnie chrapał.", "Skrócone zdanie względne (who was sitting)."),
  X("Goods bought online can be returned within 14 days.", "Towary kupione przez internet można zwrócić w ciągu 14 dni.", "Skrócone zdanie względne bierne (which are bought)."),
  X("While waiting for the bus, I read the news.", "Czekając na autobus, czytałem wiadomości.", "Spójnik while + -ing."),
  X("After graduating, she moved to Kraków.", "Po ukończeniu studiów przeprowadziła się do Krakowa.", "After + -ing.")],
 [C("-ing vs having + past participle", "-ing: równocześnie lub tuż przed; having done: wyraźnie wcześniej, zanim nastąpiło drugie.", "Having eaten, we left (najpierw jedzenie, potem wyjście)."),
  C("-ing vs past participle", "-ing: podmiot wykonuje czynność; past participle: czynność jest wykonywana na podmiocie.", "Exhausting vs exhausted – kto co komu robi."),
  C("Participle clause vs pełne zdanie", "Znaczenie podobne; forma imiesłowowa jest zwięźlejsza i formalna.", "W mailu do kolegi – pełne zdanie; w raporcie – imiesłów.")],
 [W("Walking in the park, the rain started.", "Walking in the park, I got caught in the rain.", "Wiszący imiesłów: podmiot obu części musi być ten sam (deszcz nie spacerował)."),
  W("Having finish the test, he left.", "Having finished the test, he left.", "Po having – past participle."),
  W("Built the house in 1990, they sold it.", "Having built the house in 1990, they sold it.", "Znaczenie czynne i wcześniejsze → having built."),
  W("Don't knowing the answer, I guessed.", "Not knowing the answer, I guessed.", "Przeczenie: not, bez do.")],
 ["Podmiot zdania imiesłowowego musi być taki sam jak zdania głównego (inaczej to błąd – dangling participle).",
  "Wyjątek – utarte wyrażenia: Generally speaking, Judging by…, Considering…, Given… – mogą mieć inny podmiot.",
  "Konstrukcja absolutna z własnym podmiotem jest formalna: The weather being fine, we went out."],
 [dict(en="Having weighed up the evidence, the committee rejected the proposal.", pl="Rozważywszy dowody, komisja odrzuciła propozycję.", note="Weigh up – kolokacja + having."),
  dict(en="Faced with rising costs, many families are cutting back on heating.", pl="W obliczu rosnących kosztów wiele rodzin ogranicza ogrzewanie.", note="Faced with – bardzo częste w esejach."),
  dict(en="Given the circumstances, the decision seems reasonable.", pl="Biorąc pod uwagę okoliczności, decyzja wydaje się rozsądna.", note="Given – utarte wyrażenie.")],
 [G("___ (live) in Paris for years, she knows the city well.", ["Having lived"], "Długi okres wcześniej → having lived."),
  G("___ (not / know) anyone at the party, I left early.", ["Not knowing"], "Przeczenie i przyczyna."),
  G("___ (write) in 1605, the novel is still popular.", ["Written"], "Bierne → past participle."),
  M("___ the email, she switched off the computer.", ["Having sent", "Sent", "Having send", "Sending it already"], "Having sent", "Czynność wcześniejsza.", {"Sent": "Znaczenie bierne – nie pasuje (to ona wysłała).", "Having send": "Po having – past participle (sent).", "Sending it already": "Nienaturalne, sugeruje równoczesność."}),
  G("The woman ___ (stand) by the window is my aunt.", ["standing"], "Skrócone zdanie względne czynne."),
  K("Because he didn't have a ticket, he couldn't get in.", "HAVING", "Not ___ couldn't get in.", ["having a ticket, he"], "Not having + rzeczownik."),
  K("After she had read the letter, she burst into tears.", "HAVING", "___, she burst into tears.", ["Having read the letter"], "Having + past participle."),
  E("Arriving at the station, the train had already left.", ["Arriving at the station, I found that the train had already left.", "When I arrived at the station, the train had already left.", "When we arrived at the station, the train had already left."], "Pociąg nie przyjeżdżał na stację – potrzebny właściwy podmiot.")],
 [G("___ (inform) of the delay, the passengers waited patiently.", ["Having been informed", "Informed"], "Bierne: (having been) informed."),
  G("Products ___ (make) in this factory are exported worldwide.", ["made"], "Skrócone względne bierne."),
  K("As I didn't want to wake the baby, I whispered.", "WANTING", "Not ___ the baby, I whispered.", ["wanting to wake"], "Not wanting to."),
  K("The castle, which was built in the 12th century, attracts many tourists.", "BUILT", "___ century, the castle attracts many tourists.", ["Built in the 12th", "Built in the twelfth"], "Past participle na początku."),
  M("___ by the noise, she couldn't concentrate.", ["Distracted", "Distracting", "Having distracted", "To distract"], "Distracted", "Ją rozpraszano → bierne.", {"Distracting": "Oznaczałoby, że to ona rozprasza.", "Having distracted": "Czynne i wcześniejsze – złe znaczenie.", "To distract": "Bezokolicznik celu nie pasuje."}),
  T("Skończywszy pracę, poszła do domu.", ["Having finished work, she went home.", "Having finished her work, she went home.", "Having finished working, she went home."], "Having + finished.")])
